import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('conquistando-el-caminar', 'A',
 [dict(t=1903, e=1982, titulo='Dios no te trajo para avergonzarte', txt='Dios no le gusta a los cobardes. Si usted está metido aquí es porque es un valiente de Dios. Dios no lo trajo aquí para avergonzarlo. Dios lo trajo aquí para levantarlo, para restaurar su vida, para que sea alguien que no era antes: que antes era un triste, ahora está contento; que antes era un enojado y ahora ya no tiene enojo; que antes era un iracundo y ahora ya no se enoja; que hablan mal de usted y se ríe; que su vida empezó a tener sentido. Tiene sentido su vida porque con Cristo y en Cristo tenemos sentido. Tiene usted una guía, que es el Espíritu Santo, que nos va a guiar a toda verdad […] Nos va a redargüir de pecado. Qué lindo, porque usted está hecho si le hace caso al Espíritu Santo. Pero para llenarnos nos tenemos que vaciar de lo demás: envidia, enojo, ira, contienda, disensión, pleito, para que podamos ser llenos del Espíritu Santo.'),
  dict(t=2695, e=2745, titulo='Morir a nuestros deseos', txt='Nosotros estamos hablando de andar y caminar. ¿Por qué morir? Morir a nuestras pasiones, a nuestros deseos, a nuestro futuro. Mi futuro es Dios. Los planes míos son malos, pero dice que el Señor tiene planes de bienestar para mí, y no de calamidad. Que prosperes como prospera tu alma, que camines como camina Dios. A través de los ministros, él dice que nos va guiando. Jesucristo va adelante.'),
  dict(t=3975, e=4018, titulo='Hay algo más, mucho más', txt='Creo que hay algo más, mucho más. Yo quiero que tú seas prosperado como prospera tu alma, que cuando camines te sientas feliz, tengas paz en tu corazón, estés agradando a Dios, que no haya un flato en tu corazón porque estás en pecado. Hoy hay que venir a renunciar al pecado. Hoy hay que venir a decirle: «Señor, dame una oportunidad, por favor. No quiero quedarme. No quiero que mi familia se quede, por favor».')],
 [dict(t=1710, txt='Conquistando el caminar no es para abajo; es una oportunidad de que, si tambaleaste, de ahí para arriba conquistes hasta llegar al arrebatamiento.'),
  dict(t=3205, txt='Dios quiere bendecirte hoy, pero lo que le gusta es que haya servidores que lo aman y lo sirven de todo corazón.'),
  dict(t=4427, txt='Pregúntele a Dios por qué está pasando lo que está pasando, y Dios le va a dar una respuesta para que usted salga de ahí.')],
 ['Si tropezaste en tu caminar, ¿qué paso concreto puedes dar hoy para levantarte y seguir avanzando hacia arriba?',
  '¿Qué envidia, enojo o contienda necesitas vaciar de tu corazón para ser lleno del Espíritu Santo?',
  '¿A qué deseos o planes propios necesitas morir esta semana para decirle al Señor: «Mi futuro eres tú»?'],
 inicio=550)
